    },
    {
      "check_id": "C2",
      "status": "supported",
      "finding": "The draft appropriately describes generally favorable results while qualifying that gains are not uniform; its Torch Hub comparison to DSF is a near-tie.",
      "support": ["E5", "E7", "E8"],
      "counterevidence": ["E5"],
      "unknown": "The inspected pages do not establish run-to-run variability or support generalization beyond the reported settings."
    },
    {
      "check_id": "C3",
      "status": "supported",
      "finding": "The draft accurately identifies the same-document evaluation scope and acknowledges that page 11 was not inspected.",
      "support": ["E9"],
      "counterevidence": [],
      "unknown": "Page 11 may contain qualifications or additional evidence not reflected in the draft."
    }
  ]
}

